import {clamp,mix} from './engine.js';
export class RaceAudio{
 constructor(){this.ctx=null;this.muted=false;this.active=false;this.level=0}
 init(){if(this.ctx)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const c=this.ctx=new AC();this.master=c.createGain();this.master.gain.value=this.muted?0:.34;const comp=c.createDynamicsCompressor();comp.threshold.value=-20;comp.ratio.value=5;this.master.connect(comp);comp.connect(c.destination);
  this.engine=c.createGain();this.engine.gain.value=0;this.filter=c.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=1700;this.engine.connect(this.filter);this.filter.connect(this.master);this.osc=[];
  for(let i=0;i<3;i++){const o=c.createOscillator(),g=c.createGain();o.type=i===1?'triangle':'sawtooth';o.frequency.value=80*(i+1);g.gain.value=[.5,.2,.07][i];o.connect(g);g.connect(this.engine);o.start();this.osc.push(o)}
  const buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),data=buffer.getChannelData(0);let prev=0;for(let i=0;i<data.length;i++){prev=(prev+Math.random()*2-1)/1.6;data[i]=prev}
  this.wind=c.createGain();this.wind.gain.value=0;const windSource=c.createBufferSource();windSource.buffer=buffer;windSource.loop=true;const hf=c.createBiquadFilter();hf.type='highpass';hf.frequency.value=650;windSource.connect(hf);hf.connect(this.wind);this.wind.connect(this.master);windSource.start();
  this.tire=c.createGain();this.tire.gain.value=0;const tireSource=c.createBufferSource();tireSource.buffer=buffer;tireSource.loop=true;this.tireFilter=c.createBiquadFilter();this.tireFilter.type='bandpass';this.tireFilter.frequency.value=1400;this.tireFilter.Q.value=2;tireSource.connect(this.tireFilter);this.tireFilter.connect(this.tire);this.tire.connect(this.master);tireSource.start();
 }
 start(){try{this.init();this.ctx?.resume().catch(()=>{});this.active=true}catch{}}
 setMuted(muted){this.muted=muted;if(this.ctx)this.master.gain.setTargetAtTime(muted?0:.34,this.ctx.currentTime,.12)}
 beep(high=false){if(!this.ctx||this.muted)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.frequency.value=high?1120:700;o.type='sine';g.gain.setValueAtTime(.2,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.15);o.connect(g);g.connect(this.master);o.start();o.stop(c.currentTime+.2)}
 impact(strength){if(!this.ctx)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.setValueAtTime(80,c.currentTime);o.frequency.exponentialRampToValueAtTime(25,c.currentTime+.2);g.gain.setValueAtTime(clamp(strength*2,.05,.5),c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.23);o.connect(g);g.connect(this.master);o.start();o.stop(c.currentTime+.25)}
 update(car,running,cockpit,dt){if(!this.ctx)return;const c=this.ctx,t=c.currentTime;this.level=mix(this.level,running?1:0,Math.min(1,dt*5));const pitch=car.rpm/120;this.osc.forEach((o,i)=>o.frequency.setTargetAtTime(pitch*[1,3,6][i],t,.035));this.engine.gain.setTargetAtTime((.09+car.throttle*.22)*(car.shifting>0?.3:1)*this.level*(cockpit?1:.7),t,.05);this.filter.frequency.setTargetAtTime(1100+car.throttle*1600+car.speed*7,t,.08);this.wind.gain.setTargetAtTime(Math.pow(car.speed/100,2)*.32*this.level,t,.12);this.tire.gain.setTargetAtTime((car.slip*.12+(car.offTrack&&car.speed>10?.12:0))*this.level,t,.07);this.tireFilter.frequency.setTargetAtTime(car.offTrack?650:1100+car.slip*900,t,.08)}
}
